import java.sql.*;
import java.net.URI;
import java.util.*;
import java.util.concurrent.*;

/** H2/JDBC example: custom-code uniqueness, idempotent create and authoritative expiry/status.
 * Not a production URL canonicalizer, cache, sharding layer or SSRF fetcher. */
public final class ShortLinkStore {
    private final String db;
    public ShortLinkStore(String db) throws SQLException {
        this.db = db;
        try (Connection c = connect(); Statement s = c.createStatement()) {
            s.execute("CREATE TABLE IF NOT EXISTS links(ns VARCHAR(50), code VARCHAR(50), owner_id VARCHAR(50), req_key VARCHAR(50), target VARCHAR(2048), expires BIGINT, state VARCHAR(12), PRIMARY KEY(ns,code), UNIQUE(ns,owner_id,req_key))");
        }
    }
    private Connection connect() throws SQLException { return DriverManager.getConnection(db); }
    public void create(String ns, String code, String owner, String request, String target, Long expires) throws SQLException {
        if (ns == null || owner == null || request == null || !code.matches("[A-Za-z0-9_-]{1,50}") || (expires != null && expires < 0)) throw new IllegalArgumentException();
        URI u = URI.create(target);
        if (!("https".equalsIgnoreCase(u.getScheme()) || "http".equalsIgnoreCase(u.getScheme())) || u.getHost() == null || u.getUserInfo() != null || target.length() > 2048) throw new IllegalArgumentException("invalid destination");
        try (Connection c = connect()) {
            c.setAutoCommit(false);
            try (PreparedStatement p = c.prepareStatement("INSERT INTO links VALUES(?,?,?,?,?,?, 'ACTIVE')")) {
                p.setString(1, ns); p.setString(2, code); p.setString(3, owner); p.setString(4, request); p.setString(5, target);
                if (expires == null) p.setNull(6, Types.BIGINT); else p.setLong(6, expires);
                p.executeUpdate(); c.commit();
            } catch (SQLException e) {
                if (!rollbackPreserving(c, e)) throw e;
                if (!"23505".equals(e.getSQLState())) throw e;
                try (PreparedStatement p = c.prepareStatement("SELECT code,target,expires FROM links WHERE ns=? AND owner_id=? AND req_key=?")) {
                    p.setString(1, ns); p.setString(2, owner); p.setString(3, request);
                    try (ResultSet r = p.executeQuery()) {
                        if (r.next()) {
                            long ex = r.getLong(3); Long storedExpiry = r.wasNull() ? null : ex;
                            if (code.equals(r.getString(1)) && target.equals(r.getString(2)) && Objects.equals(expires, storedExpiry)) return;
                            throw new IllegalStateException("same request with different payload");
                        }
                    }
                }
                throw new IllegalStateException("custom code already owned", e);
            }
        }
    }
    public Optional<String> resolve(String ns, String code, long now) throws SQLException {
        if (now < 0) throw new IllegalArgumentException();
        try (Connection c = connect(); PreparedStatement p = c.prepareStatement("SELECT target FROM links WHERE ns=? AND code=? AND state='ACTIVE' AND (expires IS NULL OR expires>?)")) {
            p.setString(1, ns); p.setString(2, code); p.setLong(3, now);
            try (ResultSet r = p.executeQuery()) { return r.next() ? Optional.of(r.getString(1)) : Optional.empty(); }
        }
    }
    public void revoke(String ns, String code) throws SQLException {
        try (Connection c = connect(); PreparedStatement p = c.prepareStatement("UPDATE links SET state='REVOKED' WHERE ns=? AND code=?")) {
            p.setString(1, ns); p.setString(2, code); p.executeUpdate();
        }
    }
    private static void check(boolean ok) { if (!ok) throw new AssertionError(); }
    private static void fails(RunnableSql r) throws Exception { try { r.run(); throw new AssertionError(); } catch (IllegalStateException expected) {} }
    interface RunnableSql { void run() throws Exception; }
    public static void main(String[] args) throws Exception {
        if (args.length != 1) throw new IllegalArgumentException("unique H2 path required");
        String db = "jdbc:h2:" + args[0]; ShortLinkStore s = new ShortLinkStore(db);
        s.create("a", "sale", "u", "req", "https://example.com/a", 100L);
        s.create("a", "sale", "u", "req", "https://example.com/a", 100L);
        check(s.resolve("a", "sale", 99).isPresent()); check(s.resolve("a", "sale", 100).isEmpty());
        fails(() -> s.create("a", "new", "u", "req", "https://example.com/b", 100L));
        fails(() -> s.create("a", "sale", "v", "r2", "https://example.com/b", null));
        s.create("b", "sale", "v", "r2", "https://example.com/b", null);
        check(s.resolve("b", "sale", 1000).isPresent()); s.revoke("b", "sale"); check(s.resolve("b", "sale", 1000).isEmpty());
        check(new ShortLinkStore(db).resolve("a", "sale", 99).isPresent());
        ExecutorService pool = Executors.newFixedThreadPool(8);
        try {
            List<Callable<Boolean>> work = new ArrayList<>();
            for (int i = 0; i < 20; i++) { final int n = i;
                work.add(() -> { try { s.create("race", "same", "u" + n, "r" + n, "https://example.com/" + n, null); return true; } catch (IllegalStateException e) { return false; } });
            }
            int accepted = 0; for (Future<Boolean> f : pool.invokeAll(work)) if (f.get()) accepted++;
            check(accepted == 1 && s.resolve("race", "same", 0).isPresent());
        } finally { pool.shutdownNow(); }
        System.out.println("PASS ShortLinkStore: unique code, idempotent retry, payload conflict, namespace isolation, exact expiry, revoke, reopen, 20 creators yield 1 owner");
    }

    // Keep the primary operation failure; rollback is best-effort diagnostic cleanup.
    static boolean rollbackPreserving(Connection connection, Throwable primary) {
        try {
            connection.rollback();
            return true;
        } catch (Throwable rollbackFailure) {
            if (rollbackFailure != primary) primary.addSuppressed(rollbackFailure);
            return false;
        }
    }
}
